def countAxisRectangles(points):
    pts = set((x, y) for x, y in points)
    ps = sorted(pts)
    count = 0
    for i in range(len(ps)):
        x1, y1 = ps[i]
        for j in range(i + 1, len(ps)):
            x2, y2 = ps[j]
            if x2 > x1 and y2 > y1 and (x1, y2) in pts and (x2, y1) in pts:
                count += 1
    return count
